const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], k = tok[1];
const pre = new Array(n + 1).fill(0);
for (let i = 0; i < n; i++) pre[i + 1] = pre[i] + tok[2 + i];
const INF = 1e18;
let prev = new Array(n + 1).fill(INF);
prev[0] = 0;
for (let g = 1; g <= k; g++) {
  const cur = new Array(n + 1).fill(INF);
  const solve = (lo, hi, olo, ohi) => {
    if (lo > hi) return;
    const mid = (lo + hi) >> 1;
    let best = INF, bk = olo;
    for (let j = olo; j <= Math.min(mid - 1, ohi); j++) {
      const d = pre[mid] - pre[j];
      const v = prev[j] + d * d;
      if (v < best) { best = v; bk = j; }
    }
    cur[mid] = best;
    solve(lo, mid - 1, olo, bk);
    solve(mid + 1, hi, bk, ohi);
  };
  solve(g, n, g - 1, n - 1);
  prev = cur;
}
console.log(String(prev[n]));

