import java.io.*;
import java.util.*;

public class Main {
    static long[] pre, prev, cur;
    static final long INF = Long.MAX_VALUE / 4;

    static void solve(int lo, int hi, int olo, int ohi) {
        if (lo > hi) return;
        int mid = (lo + hi) / 2;
        long best = INF;
        int bk = olo;
        for (int j = olo; j <= Math.min(mid - 1, ohi); j++) {
            long d = pre[mid] - pre[j];
            long v = prev[j] + d * d;
            if (v < best) { best = v; bk = j; }
        }
        cur[mid] = best;
        solve(lo, mid - 1, olo, bk);
        solve(mid + 1, hi, bk, ohi);
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int k = (int) in.nval;
        pre = new long[n + 1];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            pre[i + 1] = pre[i] + (long) in.nval;
        }
        prev = new long[n + 1];
        Arrays.fill(prev, INF);
        prev[0] = 0;
        for (int g = 1; g <= k; g++) {
            cur = new long[n + 1];
            Arrays.fill(cur, INF);
            solve(g, n, g - 1, n - 1);
            prev = cur;
        }
        System.out.println(prev[n]);
    }
}

