#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll INF = LLONG_MAX / 4;
vector<ll> pre, prev_, cur;

void solve(int lo, int hi, int olo, int ohi) {
    if (lo > hi) return;
    int mid = (lo + hi) / 2;
    ll best = INF;
    int bk = olo;
    for (int j = olo; j <= min(mid - 1, ohi); j++) {
        ll d = pre[mid] - pre[j];
        ll v = prev_[j] + d * d;
        if (v < best) { best = v; bk = j; }
    }
    cur[mid] = best;
    solve(lo, mid - 1, olo, bk);
    solve(mid + 1, hi, bk, ohi);
}

int main() {
    int n, k;
    scanf("%d %d", &n, &k);
    pre.assign(n + 1, 0);
    for (int i = 0; i < n; i++) {
        ll x;
        scanf("%lld", &x);
        pre[i + 1] = pre[i] + x;
    }
    prev_.assign(n + 1, INF);
    prev_[0] = 0;
    for (int g = 1; g <= k; g++) {
        cur.assign(n + 1, INF);
        solve(g, n, g - 1, n - 1);
        prev_ = cur;
    }
    printf("%lld\n", prev_[n]);
    return 0;
}
